// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface PartnerOut {
  partner_id: number;
  name: string;
  services: "Lab" | "Imaging" | "Both";
  phc_registration: string | null;
  accreditation: string | null;
  pnra_licence: string | null;
  mou_reference: string | null;
  mou_valid_from: string | null;
  mou_valid_until: string | null;
  turnaround_hours: number | null;
  quality_note: string | null;
  contact: string | null;
  address: string | null;
  is_active: boolean;
  row_version: number;
  /** Nothing is sent to a partner whose MOU has expired */
  mou_expired: boolean;
  /** Active lab tests sent to this partner by default */
  tests_sent_out: number;
}

