/** Partner laboratories and imaging centres — GET /api/v1/diagnostic-partners (who may call: holders of diagnostics.setup.manage or diagnostics.quality.view or lab.sendout.manage or imaging.order.update or lab.test.manage). */
export function listPartners(query?: { services?: "Lab" | "Imaging" | null; active_only?: boolean }): Promise<PartnerOut[]> {
  return api<PartnerOut[]>("GET", withQuery(`/diagnostic-partners`, query), undefined);
}

/** Add a partner — POST /api/v1/diagnostic-partners (who may call: holders of diagnostics.setup.manage). */
export function createPartner(body: PartnerIn): Promise<PartnerOut> {
  return api<PartnerOut>("POST", `/diagnostic-partners`, body, { idempotent: true });
}

/** Change or retire a partner — PATCH /api/v1/diagnostic-partners/{partner_id} (who may call: holders of diagnostics.setup.manage). */
export function updatePartner(partner_id: number, body: PartnerUpdateIn): Promise<PartnerOut> {
  return api<PartnerOut>("PATCH", `/diagnostic-partners/${partner_id}`, body);
}
